import { useEffect, useMemo, useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import { useToast } from '../contexts/ToastContext';
import Login from '../features/auth/Login';
import { authApi } from '../features/auth/authApi';
import ChatView from '../features/chat/ChatView';
import ProjectView from '../features/projects/ProjectView';
import DocumentsPage from '../features/documents/DocumentsPage';
import NodesPage from '../features/nodes/NodesPage';
import ModelsPage from '../features/models/ModelsPage';
import SearchPage from '../features/search/SearchPage';
import SettingsPage from '../features/settings/SettingsPage';
import AdminPage from '../features/admin/AdminPage';
import apiClient from '../api/client';
import { Menu, Moon } from 'lucide-react';
import '../styles/variables.css';
import '../styles/base.css';
import '../styles/layout.css';
import '../styles/chat.css';
import '../styles/documents.css';
import '../styles/models.css';
import '../styles/admin.css';
import '../styles/settings.css';
import '../styles/responsive.css';

const OWL_LOGO = 'data:image/png;base64,';

export default function App() {
  const { user, setUser, role, setRole, setToken, logout, isAdmin } = useAuth();
  const { darkMode, setDarkMode, accentTheme, setAccentTheme, accentThemes } = useTheme();
  const toast = useToast();
  const [view, setView] = useState('projects');
  const [projects, setProjects] = useState([]);
  const [nodes, setNodes] = useState([]);
  const [activeProject, setActiveProject] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [standaloneChats, setStandaloneChats] = useState([]);
  const [activeChatId, setActiveChatId] = useState(null);
  const [chatFilesMap, setChatFilesMap] = useState({});
  const [pendingCount, setPendingCount] = useState(0);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [showNewProjectModal, setShowNewProjectModal] = useState(false);
  const [newProjectName, setNewProjectName] = useState('');
  const [newProjectLoading, setNewProjectLoading] = useState(false);

  useEffect(() => {
    if (!user) return;

    Promise.all([
      apiClient.get('/api/projects').catch(() => []),
      apiClient.get('/api/nodes').catch(() => []),
      apiClient.get('/api/chats').catch(() => []),
      apiClient.get('/api/prefs').catch(() => ({})),
      apiClient.get('/api/auth/me').catch(() => ({ role: 'user' })),
    ]).then(([projectData, nodesData, chatData, prefs, meData]) => {
      setProjects(projectData);
      setNodes(nodesData);
      setStandaloneChats(chatData);

      if (prefs.dark_mode !== undefined) setDarkMode(Boolean(prefs.dark_mode));
      if (prefs.accent_theme && accentThemes.some((t) => t.id === prefs.accent_theme)) {
        setAccentTheme(prefs.accent_theme);
      }

      if (meData?.role) setRole(meData.role);
    });
  }, [user, setDarkMode, setAccentTheme, setRole, accentThemes]);

  useEffect(() => {
    if (!user || role !== 'admin') return;

    const refreshPending = () => {
      apiClient.get('/api/admin/users').then((users) => {
        setPendingCount(users.filter((entry) => !entry.approved).length);
      }).catch(() => {});
    };

    refreshPending();
    const timer = setInterval(refreshPending, 60000);
    return () => clearInterval(timer);
  }, [user, role]);

  useEffect(() => {
    if (!activeChatId || chatFilesMap[activeChatId]) return;

    apiClient.get(`/api/chats/${activeChatId}/files`).then((files) => {
      setChatFilesMap((current) => ({ ...current, [activeChatId]: files }));
    }).catch(() => {});
  }, [activeChatId, chatFilesMap]);

  const activeStandaloneChat = useMemo(
    () => standaloneChats.find((chat) => chat.id === activeChatId),
    [standaloneChats, activeChatId]
  );

  const closeSidebarOnMobile = () => {
    if (window.innerWidth <= 860) setSidebarOpen(false);
  };

  const loadNodes = async () => {
    try {
      const nextNodes = await apiClient.get('/api/nodes');
      setNodes(nextNodes);
    } catch {
      setNodes([]);
    }
  };

  const handleLogin = (username, nextRole) => {
    setUser(username);
    setRole(nextRole || 'user');
    setToken(localStorage.getItem('nyx_token') || null);
  };

  const handleLogout = async () => {
    await authApi.logout();
    localStorage.removeItem('nyx_token');
    localStorage.removeItem('nyx_user');
    localStorage.removeItem('nyx_role');
    logout();
    setUser(null);
    setRole('user');
    setProjects([]);
    setNodes([]);
    setStandaloneChats([]);
    setActiveProject(null);
    setActiveChatId(null);
    setChatFilesMap({});
  };

  const newProject = async () => {
    setShowNewProjectModal(true);
  };

  const createProject = async () => {
    if (!newProjectName.trim()) {
      toast('Project name cannot be empty', 'error');
      return;
    }

    setNewProjectLoading(true);
    try {
      const created = await apiClient.post('/api/projects', { name: newProjectName });
      setProjects((current) => [created, ...current]);
      setActiveProject(created);
      setView('projects');
      setShowNewProjectModal(false);
      setNewProjectName('');
    } catch (error) {
      toast(error.message || 'Failed to create project', 'error');
    } finally {
      setNewProjectLoading(false);
    }
  };

  const deleteProject = async (projectId, event) => {
    event.stopPropagation();
    await apiClient.del(`/api/projects/${projectId}`);
    setProjects((current) => current.filter((project) => project.id !== projectId));
    if (activeProject?.id === projectId) setActiveProject(null);
  };

  const newStandaloneChat = async () => {
    const created = await apiClient.post('/api/chats', { title: 'New Chat' });
    setStandaloneChats((current) => [created, ...current]);
    setActiveChatId(created.id);
    setView('standalone');
  };

  const deleteStandaloneChat = async (chatId, event) => {
    event.stopPropagation();
    await apiClient.del(`/api/chats/${chatId}`);
    setStandaloneChats((current) => current.filter((chat) => chat.id !== chatId));
    if (activeChatId === chatId) {
      const remaining = standaloneChats.find((chat) => chat.id !== chatId);
      setActiveChatId(remaining?.id ?? null);
    }
  };

  const onChatFileUploaded = (chatId, file) => {
    setChatFilesMap((current) => ({
      ...current,
      [chatId]: [...(current[chatId] || []), file],
    }));
  };

  const onChatFileDeleted = async (chatId, fileId) => {
    await apiClient.del(`/api/chats/${chatId}/files/${fileId}`).catch(() => {});
    setChatFilesMap((current) => ({
      ...current,
      [chatId]: (current[chatId] || []).filter((file) => file.id !== fileId),
    }));
  };

  if (!user) {
    return <Login onLogin={(username, role) => { setUser(username); setRole(role); }} />;
  }

  return (
    <div className="layout">
      <div className={`sidebar-overlay ${sidebarOpen ? 'open' : ''}`} onClick={() => setSidebarOpen(false)} />
      <aside className={`sidebar ${sidebarOpen ? 'open' : ''}`}>
        <div className="sidebar-header">
          <div className="sidebar-logo"><img src={OWL_LOGO} alt="Nyx" style={{ width: '100%', height: '100%', objectFit: 'contain' }} /></div>
          <div className="sidebar-title" style={{ flex: 1 }}>Nyx</div>
          <button className="sidebar-close-btn nav-icon-btn" onClick={() => setSidebarOpen(false)}>
            ×
          </button>
        </div>

        <div className="sidebar-scroll" onClick={closeSidebarOnMobile}>
          <div style={{ padding: '8px 4px' }} onClick={(event) => event.stopPropagation()}>
            <div style={{ position: 'relative' }}>
              <input
                className="input"
                style={{ paddingLeft: 30, fontSize: 12 }}
                placeholder="Search..."
                value={searchQuery}
                onChange={(event) => {
                  setSearchQuery(event.target.value);
                  if (event.target.value.length >= 2) setView('search');
                  else if (view === 'search') setView('projects');
                }}
              />
              <span style={{ position: 'absolute', left: 9, top: '50%', transform: 'translateY(-50%)', color: 'var(--text-3)' }}>⌕</span>
            </div>
          </div>

          <div className="section-label">Workspace</div>
          <div className={`nav-item ${view === 'nodes' ? 'active' : ''}`} onClick={() => setView('nodes')}><span>Nodes</span></div>
          <div className={`nav-item ${view === 'models' ? 'active' : ''}`} onClick={() => setView('models')}><span>Models</span></div>
          <div className={`nav-item ${view === 'documents' ? 'active' : ''}`} onClick={() => setView('documents')}><span>Documents</span></div>
          <div className={`nav-item ${view === 'settings' ? 'active' : ''}`} onClick={() => setView('settings')}><span>Settings</span></div>
          {isAdmin && (
            <div className={`nav-item ${view === 'admin' ? 'active' : ''}`} onClick={() => setView('admin')}>
              <span>Users</span>
              <div style={{ marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 4 }}>
                {pendingCount > 0 && (
                  <span className="badge" style={{ fontSize: 9, padding: '1px 5px', background: 'rgba(251,191,36,0.15)', color: 'var(--amber)' }}>
                    {pendingCount} pending
                  </span>
                )}
                <span className="badge badge-violet" style={{ fontSize: 9, padding: '1px 5px' }}>admin</span>
              </div>
            </div>
          )}

          <div className="section-label" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', paddingRight: 8 }}>
            <span>Chats</span>
            <button className="nav-icon-btn" onClick={newStandaloneChat}>+</button>
          </div>
          {standaloneChats.map((chat) => (
            <div
              key={chat.id}
              className={`nav-item ${view === 'standalone' && activeChatId === chat.id ? 'active' : ''}`}
              onClick={() => { setActiveChatId(chat.id); setView('standalone'); }}
            >
              <span style={{ flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{chat.title}</span>
              <div className="nav-item-actions"><button className="nav-icon-btn" onClick={(event) => deleteStandaloneChat(chat.id, event)}>×</button></div>
            </div>
          ))}

          <div className="section-label" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', paddingRight: 8 }}>
            <span>Projects</span>
            <button className="nav-icon-btn" onClick={newProject}>+</button>
          </div>
          {projects.map((project) => (
            <div
              key={project.id}
              className={`nav-item ${view === 'projects' && activeProject?.id === project.id ? 'active' : ''}`}
              onClick={() => { setActiveProject(project); setView('projects'); }}
            >
              <span style={{ flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{project.name}</span>
              <div className="nav-item-actions"><button className="nav-icon-btn" onClick={(event) => deleteProject(project.id, event)}>×</button></div>
            </div>
          ))}
          {projects.length === 0 && <div style={{ fontSize: 12, color: 'var(--text-3)', padding: '6px 10px' }}>No projects yet</div>}
        </div>

        <div className="sidebar-footer">
          <button className="btn btn-ghost btn-sm" style={{ width: '100%', justifyContent: 'flex-start', color: 'var(--text-2)' }} onClick={handleLogout}>
            Sign out
          </button>
        </div>
      </aside>

      <div className="main">
        <div className="main-header">
          <button className="hamburger-btn" onClick={() => setSidebarOpen(true)} aria-label="Open menu" title="Open menu">
            <Menu size={18} />
          </button>
          {view === 'projects' && activeProject && <div className="main-title">{activeProject.name}</div>}
          {view === 'standalone' && activeStandaloneChat && <div className="main-title">{activeStandaloneChat.title}</div>}
          {view === 'nodes' && <div className="main-title">Nodes</div>}
          {view === 'models' && <div className="main-title">Models</div>}
          {view === 'documents' && <div className="main-title">Documents</div>}
          {view === 'settings' && <div className="main-title">Settings</div>}
          {view === 'search' && <div className="main-title">Search</div>}
          {view === 'admin' && <div className="main-title">Users</div>}
          <div className="header-actions">
            <button className="btn btn-ghost btn-sm btn-icon" title="Toggle dark mode" onClick={() => setDarkMode((current) => !current)}>
              <Moon size={16} />
            </button>
          </div>
        </div>

        {view === 'projects' && activeProject && (
          <ProjectView
            project={activeProject}
            nodes={nodes}
            onUpdate={(updated) => {
              setProjects((prev) => prev.map((p) => (p.id === updated.id ? updated : p)));
              setActiveProject(updated);
            }}
          />
        )}
        {view === 'projects' && !activeProject && (
          <div className="empty" style={{ flex: 1 }}>
            <div className="empty-icon">◎</div>
            <div>Select a project or create one</div>
            <button className="btn btn-primary btn-sm" onClick={newProject}>New project</button>
          </div>
        )}

        {view === 'standalone' && activeChatId && activeStandaloneChat && (
          <ChatView
            chatId={activeChatId}
            projectSystemPrompt={null}
            projectFiles={[]}
            chatFiles={chatFilesMap[activeChatId] || []}
            onChatFileUploaded={onChatFileUploaded}
            onChatFileDeleted={onChatFileDeleted}
            nodes={nodes}
            onTitleUpdate={(cid, title) => {
              setStandaloneChats((prev) => prev.map((c) => (c.id === cid ? { ...c, title } : c)));
            }}
            isStandalone={true}
          />
        )}

        {view === 'search' && <SearchPage />}
        {view === 'nodes' && <NodesPage nodes={nodes} onRefresh={loadNodes} />}
        {view === 'models' && <ModelsPage nodes={nodes} />}
        {view === 'documents' && <DocumentsPage />}
        {view === 'settings' && <SettingsPage />}
        {view === 'admin' && <AdminPage />}
      </div>

      {showNewProjectModal && (
        <div className="modal-overlay" onClick={() => setShowNewProjectModal(false)}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <div className="modal-title">New Project</div>
              <button className="modal-close" onClick={() => setShowNewProjectModal(false)}>×</button>
            </div>
            <div className="modal-body">
              <input
                className="input"
                placeholder="Project name"
                value={newProjectName}
                onChange={(e) => setNewProjectName(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') createProject();
                  if (e.key === 'Escape') setShowNewProjectModal(false);
                }}
                autoFocus
              />
            </div>
            <div className="modal-footer">
              <button className="btn btn-ghost" onClick={() => setShowNewProjectModal(false)}>Cancel</button>
              <button className="btn btn-primary" onClick={createProject} disabled={newProjectLoading || !newProjectName.trim()}>
                {newProjectLoading ? <span className="spinner" /> : 'Create'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

